CREATE MATERIALIZED VIEW non_leaf_1110 AS
SELECT mi1.id AS mi1_id, mi1.movie_id AS mi1_movie_id, mi1.info_type_id AS mi1_info_type_id, mi1.info AS mi1_info, mi1.note AS mi1_note, ci.id AS ci_id, ci.person_id AS ci_person_id, ci.movie_id AS ci_movie_id, ci.person_role_id AS ci_person_role_id, ci.note AS ci_note, ci.nr_order AS ci_nr_order, ci.role_id AS ci_role_id, rt.id AS rt_id, rt.role AS rt_role, pi.id AS pi_id, pi.person_id AS pi_person_id, pi.info_type_id AS pi_info_type_id, pi.info AS pi_info, pi.note AS pi_note, n.id AS n_id, n.name AS n_name, n.imdb_index AS n_imdb_index, n.imdb_id AS n_imdb_id, n.gender AS n_gender, n.name_pcode_cf AS n_name_pcode_cf, n.name_pcode_nf AS n_name_pcode_nf, n.surname_pcode AS n_surname_pcode, n.md5sum AS n_md5sum
FROM movie_info AS mi1, cast_info AS ci, role_type AS rt, person_info AS pi, name AS n
WHERE mi1.movie_id = ci.movie_id AND mi1.info ~~* '%roma%' AND mi1.info_type_id = 16 AND ci.person_id = n.id AND ci.role_id = rt.id AND rt.role IN ('actor', 'composer', 'director', 'editor', 'miscellaneous crew', 'producer') AND pi.info ~~* '%194%' AND pi.info_type_id = 23 AND n.id = pi.person_id;